package de.terrestris.shoguncore.util.json;
public class ShogunCoreJsonObjectMapper extends ObjectMapper {
    private static final long serialVersionUID = 1L;
    public ShogunCoreJsonObjectMapper() {
        super();
        // register the joda module to support the joda time types, which are
        // used in shogun
        this.registerModule(new JodaModule());
        // register JTS geometry types
        this.registerModule(new JtsModule());
        // StdDateFormat is ISO8601 since jackson 2.9
        configure(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS, false);
        setDateFormat(new StdDateFormat());
        setTimeZone(TimeZone.getDefault());
    }
}
package de.terrestris.shoguncore.model;
@MappedSuperclass
@Cacheable
@Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
public abstract class PersistentObject implements Serializable {
    private static final long serialVersionUID = 1L;
    @Id
    @GeneratedValue(strategy = GenerationType.TABLE)
    // The column annotation is used by hibernate for the column creation, e.g.
    // to build constraints like nullable
    @Column(updatable = false, nullable = false)
    private final Integer id = null;
    @Column(updatable = false)
    @Type(type = "org.jadira.usertype.dateandtime.joda.PersistentDateTime")
    private final ReadableDateTime created;
    @Column
    @Type(type = "org.jadira.usertype.dateandtime.joda.PersistentDateTime")
    private ReadableDateTime modified;
    @ManyToMany
    @JoinTable(
        name = "USERPERMISSIONS",
        joinColumns = @JoinColumn(name = "ENTITY_ID"))
    @JsonIgnore
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.JOIN)
    private Map<User, PermissionCollection> userPermissions = new HashMap<User, PermissionCollection>();
    @ManyToMany
    @JoinTable(
        name = "GROUPPERMISSIONS",
        joinColumns = @JoinColumn(name = "ENTITY_ID"))
    @JsonIgnore
    @Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
    @Fetch(FetchMode.JOIN)
    private Map<UserGroup, PermissionCollection> groupPermissions = new HashMap<UserGroup, PermissionCollection>();
    protected PersistentObject() {
        this.created = DateTime.now();
        this.modified = DateTime.now();
    }
    public Integer getId() {
        return id;
    }
    @JsonIgnore
    public ReadableDateTime getCreated() {
        return created;
    }
    @JsonIgnore
    public ReadableDateTime getModified() {
        return modified;
    }
    public void setModified(ReadableDateTime modified) {
        this.modified = modified;
    }
    public Map<User, PermissionCollection> getUserPermissions() {
        return userPermissions;
    }
    public void setUserPermissions(Map<User, PermissionCollection> userPermissions) {
        this.userPermissions = userPermissions;
    }
    public Map<UserGroup, PermissionCollection> getGroupPermissions() {
        return groupPermissions;
    }
    public void setGroupPermissions(
        Map<UserGroup, PermissionCollection> groupPermissions) {
        this.groupPermissions = groupPermissions;
    }
    public int hashCode() {
        // two randomly chosen prime numbers
        return new HashCodeBuilder(17, 43).
            append(getClass()).
            append(getCreated()).
            toHashCode();
    }
    public boolean equals(Object obj) {
        if (!(obj instanceof PersistentObject)) {
            return false;
        }
        PersistentObject other = (PersistentObject) obj;
        return new EqualsBuilder().
            append(getClass(), other.getClass()).
            append(getCreated(), other.getCreated()).
            isEquals();
    }
    public String toString() {
        return new ToStringBuilder(this)
            .append("id", getId())
            .append("created", getCreated())
            .append("modified", getModified())
            .toString();
    }
}
package de.terrestris.shoguncore.model;
@Entity
@Table
@Inheritance(strategy = InheritanceType.JOINED)
@Cacheable
@Cache(usage = CacheConcurrencyStrategy.READ_WRITE)
public class Person extends PersistentObject {
    private static final long serialVersionUID = 1L;
    @Column
    private String firstName;
    @Column
    private String lastName;
    @Column
    private String email;
    @Column
    @Type(type = "org.jadira.usertype.dateandtime.joda.PersistentLocalDate")
    private LocalDate birthday;
    @Column
    private Locale language;
    public Person() {
    }
    public Person(String firstName, String lastName) {
        this.firstName = firstName;
        this.lastName = lastName;
    }
    public Person(String firstName, String lastName, String email) {
        this.firstName = firstName;
        this.lastName = lastName;
        this.email = email;
    }
    public String getFirstName() {
        return firstName;
    }
    public void setFirstName(String firstName) {
        this.firstName = firstName;
    }
    public String getLastName() {
        return lastName;
    }
    public void setLastName(String lastName) {
        this.lastName = lastName;
    }
    public String getEmail() {
        return email;
    }
    public void setEmail(String email) {
        this.email = email;
    }
    public LocalDate getBirthday() {
        return birthday;
    }
    public void setBirthday(LocalDate birthday) {
        this.birthday = birthday;
    }
    public Locale getLanguage() {
        return language;
    }
    public void setLanguage(Locale language) {
        this.language = language;
    }
    @Override
    public int hashCode() {
        // two randomly chosen prime numbers
        return new HashCodeBuilder(19, 53).
            appendSuper(super.hashCode()).
            append(getFirstName()).
            append(getLastName()).
            append(getEmail()).
            append(getBirthday()).
            append(getLanguage()).
            toHashCode();
    }
    @Override
    public boolean equals(Object obj) {
        if (!(obj instanceof Person)) {
            return false;
        }
        Person other = (Person) obj;
        return new EqualsBuilder().
            appendSuper(super.equals(other)).
            append(getFirstName(), other.getFirstName()).
            append(getLastName(), other.getLastName()).
            append(getEmail(), other.getEmail()).
            append(getBirthday(), other.getBirthday()).
            append(getLanguage(), other.getLanguage()).
            isEquals();
    }
    public String toString() {
        return new ToStringBuilder(this)
            .appendSuper(super.toString())
            .append("firstName", getFirstName())
            .append("lastName", getLastName())
            .append("eMail", getEmail())
            .append("birthday", getBirthday())
            .append("language", getLanguage())
