//! Entity specifications: field lists (in Jackson's output order), default
//! ("new instance") values, Jackson-like deserialisation and serialisation.

use crate::javafmt::java_double_to_string;
use serde_json::{json, Map, Value};

pub type Obj = Map<String, Value>;

/// Marker key for objects that were built from a request body (detached
/// objects). Never serialised.
pub const NEW_FLAG: &str = "$new";

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    User,
    Role,
    Group,
    Layer,
    Appearance,
    DsImage,
    DsTile,
    DsWfs,
    DsWmts,
    DsXyz,
    Extent,
    TileGrid,
    WmtsTileGrid,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Ty {
    Id,
    Str,
    BoolP,
    BoolW,
    IntP,
    IntW,
    DblW,
    Locale,
    Date,
    Props,
    Point,
    StrList,
    DblList,
    Obj(Kind),
    ObjSet(Kind),
    IdSet(Kind),
    Abstract,
}

#[derive(Clone, Copy, Debug)]
pub struct F {
    pub name: &'static str,
    pub ty: Ty,
    pub write_only: bool,
}

const fn f(name: &'static str, ty: Ty) -> F {
    F { name, ty, write_only: false }
}

const IGNORED: [&str; 4] = ["created", "modified", "userPermissions", "groupPermissions"];

const DS_BASE: [F; 5] = [
    f("id", Ty::Id),
    f("name", Ty::Str),
    f("type", Ty::Str),
    f("url", Ty::Str),
    f("format", Ty::Str),
];

const IMAGE_FIELDS: [F; 7] = [
    f("width", Ty::IntP),
    f("height", Ty::IntP),
    f("version", Ty::Str),
    f("layerNames", Ty::Str),
    f("layerStyles", Ty::Str),
    f("requestableByPath", Ty::BoolW),
    f("customRequestPath", Ty::Str),
];

pub fn fields(kind: Kind) -> Vec<F> {
    match kind {
        Kind::User => vec![
            f("id", Ty::Id),
            f("firstName", Ty::Str),
            f("lastName", Ty::Str),
            f("email", Ty::Str),
            f("birthday", Ty::Date),
            f("language", Ty::Locale),
            f("accountName", Ty::Str),
            F { name: "password", ty: Ty::Str, write_only: true },
            f("active", Ty::BoolP),
            f("roles", Ty::ObjSet(Kind::Role)),
            f("userGroups", Ty::IdSet(Kind::Group)),
        ],
        Kind::Role => vec![f("id", Ty::Id), f("name", Ty::Str), f("description", Ty::Str)],
        Kind::Group => vec![
            f("id", Ty::Id),
            f("name", Ty::Str),
            f("owner", Ty::Obj(Kind::User)),
            f("members", Ty::ObjSet(Kind::User)),
            f("roles", Ty::ObjSet(Kind::Role)),
        ],
        Kind::Layer => vec![
            f("id", Ty::Id),
            f("name", Ty::Str),
            f("description", Ty::Str),
            f("source", Ty::Abstract),
            f("appearance", Ty::Obj(Kind::Appearance)),
        ],
        Kind::Appearance => vec![
            f("id", Ty::Id),
            f("attribution", Ty::Str),
            f("hoverable", Ty::BoolW),
            f("clickable", Ty::BoolW),
            f("hoverTemplate", Ty::Str),
            f("properties", Ty::Props),
            f("name", Ty::Str),
            f("maxResolution", Ty::DblW),
            f("minResolution", Ty::DblW),
            f("opacity", Ty::DblW),
            f("visible", Ty::BoolW),
        ],
        Kind::DsImage => {
            let mut v = DS_BASE.to_vec();
            v.extend_from_slice(&IMAGE_FIELDS);
            v
        }
        Kind::DsTile => {
            let mut v = DS_BASE.to_vec();
            v.extend_from_slice(&IMAGE_FIELDS);
            v.push(f("tileGrid", Ty::Obj(Kind::TileGrid)));
            v.push(f("requestWithTiled", Ty::BoolW));
            v
        }
        Kind::DsWfs => {
            let mut v = DS_BASE.to_vec();
            v.push(f("version", Ty::Str));
            v.push(f("typeName", Ty::Str));
            v.push(f("typeNames", Ty::Str));
            v
        }
        Kind::DsWmts => {
            let mut v = DS_BASE.to_vec();
            v.push(f("tileGrid", Ty::Obj(Kind::WmtsTileGrid)));
            v.push(f("urls", Ty::StrList));
            v.push(f("wmtsLayer", Ty::Str));
            v.push(f("wmtsStyle", Ty::Str));
            v.push(f("projection", Ty::Str));
            v.push(f("matrixSet", Ty::Str));
            v.push(f("requestEncoding", Ty::Str));
            v.push(f("capabilitiesUrl", Ty::Str));
            v
        }
        Kind::DsXyz => {
            let mut v = DS_BASE.to_vec();
            v.push(f("center", Ty::Point));
            v.push(f("extent", Ty::Obj(Kind::Extent)));
            v.push(f("resolutions", Ty::DblList));
            v.push(f("tileSize", Ty::IntW));
            v
        }
        Kind::Extent => vec![f("id", Ty::Id), f("lowerLeft", Ty::Point), f("upperRight", Ty::Point)],
        Kind::TileGrid => vec![
            f("id", Ty::Id),
            f("type", Ty::Str),
            f("tileGridOrigin", Ty::Point),
            f("tileGridExtent", Ty::Obj(Kind::Extent)),
            f("tileSize", Ty::IntW),
            f("tileGridResolutions", Ty::DblList),
        ],
        Kind::WmtsTileGrid => vec![
            f("id", Ty::Id),
            f("type", Ty::Str),
            f("tileGridOrigin", Ty::Point),
            f("tileGridExtent", Ty::Obj(Kind::Extent)),
            f("tileSize", Ty::IntW),
            f("tileGridResolutions", Ty::DblList),
            f("matrixIds", Ty::StrList),
        ],
    }
}

/// A fresh instance as constructed by the entity's default constructor.
pub fn new_instance(kind: Kind) -> Obj {
    let mut o = Obj::new();
    for fd in fields(kind) {
        let v = match fd.ty {
            Ty::BoolP => Value::Bool(false),
            Ty::IntP => json!(0),
            Ty::Props => Value::Object(Map::new()),
            Ty::ObjSet(_) | Ty::IdSet(_) => Value::Array(vec![]),
            _ => Value::Null,
        };
        o.insert(fd.name.to_string(), v);
    }
    match kind {
        Kind::TileGrid | Kind::WmtsTileGrid => {
            o.insert("tileSize".into(), json!(256));
        }
        Kind::DsTile => {
            o.insert("requestWithTiled".into(), Value::Bool(true));
        }
        Kind::DsXyz => {
            o.insert("resolutions".into(), Value::Array(vec![]));
        }
        _ => {}
    }
    o
}

/// Serialise an in-memory entity the way Jackson does (field order, no
/// write-only properties, ids only for `IdSet`s).
pub fn serialize(kind: Kind, o: &Obj) -> Value {
    let mut out = Map::new();
    for fd in fields(kind) {
        if fd.write_only {
            continue;
        }
        let v = o.get(fd.name).cloned().unwrap_or(Value::Null);
        let v = match (fd.ty, &v) {
            (Ty::Obj(k), Value::Object(inner)) => serialize(k, inner),
            (Ty::ObjSet(k), Value::Array(items)) => Value::Array(
                items
                    .iter()
                    .map(|i| match i {
                        Value::Object(inner) => serialize(k, inner),
                        other => other.clone(),
                    })
                    .collect(),
            ),
            _ => v,
        };
        out.insert(fd.name.to_string(), v);
    }
    Value::Object(out)
}

/// Context of a deserialisation run.
#[derive(Default)]
pub struct DeCtx {
    /// ids of user groups that were referenced by id (`userGroups`)
    pub group_refs: Vec<i32>,
}

type R<T> = Result<T, ()>;

pub fn apply(kind: Kind, target: &mut Obj, json: &Value, ctx: &mut DeCtx) -> R<()> {
    let m = json.as_object().ok_or(())?;
    let fds = fields(kind);
    for (k, v) in m {
        if IGNORED.contains(&k.as_str()) {
            continue;
        }
        let fd = fds.iter().find(|fd| fd.name == k).ok_or(())?;
        let nv = convert(fd.ty, v, ctx)?;
        target.insert(k.clone(), nv);
    }
    Ok(())
}

fn num_to_text(n: &serde_json::Number) -> String {
    if let Some(i) = n.as_i64() {
        i.to_string()
    } else if let Some(u) = n.as_u64() {
        u.to_string()
    } else {
        java_double_to_string(n.as_f64().unwrap_or(0.0))
    }
}

fn to_int(v: &Value, primitive: bool) -> R<Value> {
    match v {
        Value::Null => Ok(if primitive { json!(0) } else { Value::Null }),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                if i >= i32::MIN as i64 && i <= i32::MAX as i64 {
                    Ok(json!(i))
                } else {
                    Err(())
                }
            } else if let Some(fl) = n.as_f64() {
                let t = fl.trunc();
                if t.is_finite() && t >= i32::MIN as f64 && t <= i32::MAX as f64 {
                    Ok(json!(t as i64))
                } else {
                    Err(())
                }
            } else {
                Err(())
            }
        }
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                return Ok(if primitive { json!(0) } else { Value::Null });
            }
            if t == "null" {
                return Ok(if primitive { json!(0) } else { Value::Null });
            }
            t.parse::<i32>().map(|i| json!(i)).map_err(|_| ())
        }
        _ => Err(()),
    }
}

fn to_bool(v: &Value, primitive: bool) -> R<Value> {
    let null = if primitive { Value::Bool(false) } else { Value::Null };
    match v {
        Value::Null => Ok(null),
        Value::Bool(b) => Ok(Value::Bool(*b)),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Ok(Value::Bool(i != 0))
            } else {
                Err(())
            }
        }
        Value::String(s) => {
            let t = s.trim();
            match t {
                "" | "null" => Ok(null),
                "true" | "True" | "TRUE" => Ok(Value::Bool(true)),
                "false" | "False" | "FALSE" => Ok(Value::Bool(false)),
                _ => Err(()),
            }
        }
        _ => Err(()),
    }
}

fn to_double(v: &Value) -> R<Value> {
    match v {
        Value::Null => Ok(Value::Null),
        Value::Number(n) => Ok(json!(n.as_f64().ok_or(())?)),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() || t == "null" {
                return Ok(Value::Null);
            }
            match t.parse::<f64>() {
                Ok(d) if d.is_finite() => Ok(json!(d)),
                _ => Err(()),
            }
        }
        _ => Err(()),
    }
}

pub fn normalize_locale(s: &str) -> String {
    let (lang, country, variant): (String, String, String) = if s.contains('_') {
        let mut it = s.splitn(3, '_');
        let a = it.next().unwrap_or("").to_string();
        let rest = it.collect::<Vec<_>>();
        match rest.len() {
            1 => {
                // "xx_YY" or "xx_YY_VAR" (splitn gave 3 parts max)
                (a, rest[0].to_string(), String::new())
            }
            2 => (a, rest[0].to_string(), rest[1].to_string()),
            _ => (a, String::new(), String::new()),
        }
    } else if s.contains('-') {
        let mut it = s.splitn(3, '-');
        let a = it.next().unwrap_or("").to_string();
        let b = it.next().unwrap_or("").to_string();
        let c = it.next().unwrap_or("").to_string();
        (a, b, c)
    } else {
        (s.to_string(), String::new(), String::new())
    };
    let lang = lang.to_lowercase();
    let country = country.to_uppercase();
    let mut out = lang.clone();
    if !country.is_empty() || !variant.is_empty() {
        out.push('_');
        out.push_str(&country);
        if !variant.is_empty() {
            out.push('_');
            out.push_str(&variant);
        }
    }
    out
}

fn parse_date(s: &str) -> Option<String> {
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() != 3 {
        return None;
    }
    let y: i32 = parts[0].parse().ok()?;
    let m: u32 = parts[1].parse().ok()?;
    let d: u32 = parts[2].parse().ok()?;
    if parts[0].len() < 4
        || parts[1].is_empty()
        || parts[1].len() > 2
        || parts[2].is_empty()
        || parts[2].len() > 2
        || !parts.iter().all(|p| p.chars().all(|c| c.is_ascii_digit()))
    {
        return None;
    }
    date_string(y, m, d)
}

fn date_string(y: i32, m: u32, d: u32) -> Option<String> {
    if !(1..=12).contains(&m) || d < 1 {
        return None;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let dim = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        _ => {
            if leap {
                29
            } else {
                28
            }
        }
    };
    if d > dim {
        return None;
    }
    Some(format!("{:04}-{:02}-{:02}", y, m, d))
}

fn to_str(v: &Value) -> R<Value> {
    match v {
        Value::Null => Ok(Value::Null),
        Value::String(s) => Ok(Value::String(s.clone())),
        Value::Bool(b) => Ok(Value::String(b.to_string())),
        Value::Number(n) => Ok(Value::String(num_to_text(n))),
        _ => Err(()),
    }
}

fn convert(ty: Ty, v: &Value, ctx: &mut DeCtx) -> R<Value> {
    match ty {
        Ty::Id => to_int(v, false),
        Ty::Str => to_str(v),
        Ty::BoolP => to_bool(v, true),
        Ty::BoolW => to_bool(v, false),
        Ty::IntP => to_int(v, true),
        Ty::IntW => to_int(v, false),
        Ty::DblW => to_double(v),
        Ty::Locale => match v {
            Value::Null => Ok(Value::Null),
            Value::String(s) => Ok(Value::String(normalize_locale(s))),
            _ => Err(()),
        },
        Ty::Date => match v {
            Value::Null => Ok(Value::Null),
            Value::String(s) => {
                if s.is_empty() {
                    Ok(Value::Null)
                } else {
                    parse_date(s).map(Value::String).ok_or(())
                }
            }
            Value::Array(a) if a.len() == 3 => {
                let n: Vec<i64> = a.iter().filter_map(|x| x.as_i64()).collect();
                if n.len() != 3 {
                    return Err(());
                }
                date_string(n[0] as i32, n[1] as u32, n[2] as u32)
                    .map(Value::String)
                    .ok_or(())
            }
            _ => Err(()),
        },
        Ty::Props => match v {
            Value::Null => Ok(Value::Null),
            Value::Object(_) => Ok(v.clone()),
            _ => Err(()),
        },
        Ty::Point => match v {
            Value::Null => Ok(Value::Null),
            Value::Object(m) => {
                let mut out = Map::new();
                out.insert("x".into(), json!(0.0));
                out.insert("y".into(), json!(0.0));
                for (k, val) in m {
                    if k != "x" && k != "y" {
                        return Err(());
                    }
                    let d = match val {
                        Value::Null => json!(0.0),
                        other => {
                            let dv = to_double(other)?;
                            if dv.is_null() {
                                json!(0.0)
                            } else {
                                dv
                            }
                        }
                    };
                    out.insert(k.clone(), d);
                }
                Ok(Value::Object(out))
            }
            _ => Err(()),
        },
        Ty::StrList => match v {
            Value::Null => Ok(Value::Null),
            Value::Array(a) => Ok(Value::Array(
                a.iter().map(to_str).collect::<R<Vec<_>>>()?,
            )),
            _ => Err(()),
        },
        Ty::DblList => match v {
            Value::Null => Ok(Value::Null),
            Value::Array(a) => Ok(Value::Array(
                a.iter().map(to_double).collect::<R<Vec<_>>>()?,
            )),
            _ => Err(()),
        },
        Ty::Obj(k) => match v {
            Value::Null => Ok(Value::Null),
            Value::Object(_) => {
                let mut o = new_instance(k);
                apply(k, &mut o, v, ctx)?;
                o.insert(NEW_FLAG.into(), Value::Bool(true));
                Ok(Value::Object(o))
            }
            _ => Err(()),
        },
        Ty::ObjSet(k) => match v {
            Value::Null => Ok(Value::Null),
            Value::Array(a) => {
                let mut out = vec![];
                for item in a {
                    match item {
                        Value::Object(_) => {
                            let mut o = new_instance(k);
                            apply(k, &mut o, item, ctx)?;
                            o.insert(NEW_FLAG.into(), Value::Bool(true));
                            out.push(Value::Object(o));
                        }
                        _ => return Err(()),
                    }
                }
                Ok(Value::Array(out))
            }
            _ => Err(()),
        },
        Ty::IdSet(k) => match v {
            Value::Null => Ok(Value::Null),
            Value::Array(a) => {
                let mut out = vec![];
                for item in a {
                    let id = match item {
                        Value::Object(_) => {
                            let mut o = new_instance(k);
                            apply(k, &mut o, item, ctx)?;
                            o.get("id").and_then(|x| x.as_i64())
                        }
                        other => to_int(other, false)?.as_i64(),
                    };
                    let id = id.ok_or(())? as i32;
                    ctx.group_refs.push(id);
                    if !out.contains(&json!(id)) {
                        out.push(json!(id));
                    }
                }
                Ok(Value::Array(out))
            }
            _ => Err(()),
        },
        Ty::Abstract => match v {
            Value::Null => Ok(Value::Null),
            _ => Err(()),
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn user_roundtrip() {
        let mut u = new_instance(Kind::User);
        let mut ctx = DeCtx::default();
        apply(
            Kind::User,
            &mut u,
            &json!({"accountName":"a","active":"true","roles":[{"id":2}],"userGroups":[6],"language":"de-DE","birthday":[2000,1,2]}),
            &mut ctx,
        )
        .unwrap();
        let s = serialize(Kind::User, &u);
        assert_eq!(s["active"], json!(true));
        assert_eq!(s["language"], json!("de_DE"));
        assert_eq!(s["birthday"], json!("2000-01-02"));
        assert_eq!(s["roles"][0]["id"], json!(2));
        assert_eq!(s["roles"][0]["name"], Value::Null);
        assert_eq!(s["userGroups"], json!([6]));
        assert!(s.get("password").is_none());
        assert_eq!(ctx.group_refs, vec![6]);
    }

    #[test]
    fn unknown_and_ignored_properties() {
        let mut u = new_instance(Kind::Role);
        let mut ctx = DeCtx::default();
        assert!(apply(Kind::Role, &mut u, &json!({"name":"x","created":"y","userPermissions":{}}), &mut ctx).is_ok());
        assert!(apply(Kind::Role, &mut u, &json!({"foo":1}), &mut ctx).is_err());
        assert!(apply(Kind::User, &mut new_instance(Kind::User), &json!({"active":"yes"}), &mut ctx).is_err());
        assert!(apply(Kind::User, &mut new_instance(Kind::User), &json!({"birthday":"2000-13-01"}), &mut ctx).is_err());
    }

    #[test]
    fn layer_source_is_abstract() {
        let mut l = new_instance(Kind::Layer);
        let mut ctx = DeCtx::default();
        assert!(apply(Kind::Layer, &mut l, &json!({"source":{"id":1}}), &mut ctx).is_err());
        assert!(apply(Kind::Layer, &mut l, &json!({"source":null}), &mut ctx).is_ok());
    }

    #[test]
    fn locale() {
        assert_eq!(normalize_locale("zz-ZZ"), "zz_ZZ");
        assert_eq!(normalize_locale("de_de"), "de_DE");
        assert_eq!(normalize_locale("fr"), "fr");
        assert_eq!(normalize_locale(""), "");
    }
}

