//! Loading entities (with the associations Hibernate fetches eagerly) from the
//! database into in-memory [`Obj`]s.

use crate::javafmt::property_from_db;
use crate::spec::{new_instance, Kind, Obj};
use serde_json::{json, Value};
use sqlx::{PgPool, Row};
use std::collections::{HashMap, HashSet};

pub type Res<T> = Result<T, sqlx::Error>;

fn sv(v: Option<String>) -> Value {
    v.map(Value::String).unwrap_or(Value::Null)
}
fn iv(v: Option<i32>) -> Value {
    v.map(|x| json!(x)).unwrap_or(Value::Null)
}
fn bv(v: Option<bool>) -> Value {
    v.map(Value::Bool).unwrap_or(Value::Null)
}
fn dv(v: Option<f64>) -> Value {
    v.map(|x| json!(x)).unwrap_or(Value::Null)
}
fn point(x: Option<f64>, y: Option<f64>) -> Value {
    if x.is_none() && y.is_none() {
        Value::Null
    } else {
        json!({"x": x.unwrap_or(0.0), "y": y.unwrap_or(0.0)})
    }
}

pub fn decode_resolution(bytes: &[u8]) -> f64 {
    if bytes.len() >= 8 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&bytes[bytes.len() - 8..]);
        f64::from_be_bytes(b)
    } else {
        0.0
    }
}

const DOUBLE_PREFIX: [u8; 0x4d] = [
    0xac, 0xed, 0x00, 0x05, 0x73, 0x72, 0x00, 0x10, b'j', b'a', b'v', b'a', b'.', b'l', b'a', b'n', b'g', b'.',
    b'D', b'o', b'u', b'b', b'l', b'e', 0x80, 0xb3, 0xc2, 0x4a, 0x29, 0x6b, 0xfb, 0x04, 0x02, 0x00, 0x01, b'D',
    0x00, 0x05, b'v', b'a', b'l', b'u', b'e', 0x78, 0x72, 0x00, 0x10, b'j', b'a', b'v', b'a', b'.', b'l', b'a',
    b'n', b'g', b'.', b'N', b'u', b'm', b'b', b'e', b'r', 0x86, 0xac, 0x95, 0x1d, 0x0b, 0x94, 0xe0, 0x8b, 0x02,
    0x00, 0x00, 0x78, 0x70,
];

/// Java serialisation of a `java.lang.Double`.
pub fn encode_resolution(d: f64) -> Vec<u8> {
    let mut v = DOUBLE_PREFIX.to_vec();
    v.extend_from_slice(&d.to_be_bytes());
    v
}

pub async fn roles(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, Obj>> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query("select id, name, description from roles where id = any($1)")
        .bind(ids.to_vec())
        .fetch_all(pool)
        .await?;
    for r in rows {
        let mut o = new_instance(Kind::Role);
        let id: i32 = r.get("id");
        o.insert("id".into(), json!(id));
        o.insert("name".into(), sv(r.get("name")));
        o.insert("description".into(), sv(r.get("description")));
        out.insert(id, o);
    }
    Ok(out)
}

pub async fn users(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, Obj>> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query(
        "select u.id, u.accountname, u.active, p.firstname, p.lastname, p.email, \
         p.birthday::text as birthday, p.language \
         from users u join persons p on p.id = u.id where u.id = any($1)",
    )
    .bind(ids.to_vec())
    .fetch_all(pool)
    .await?;
    for r in rows {
        let mut o = new_instance(Kind::User);
        let id: i32 = r.get("id");
        o.insert("id".into(), json!(id));
        o.insert("firstName".into(), sv(r.get("firstname")));
        o.insert("lastName".into(), sv(r.get("lastname")));
        o.insert("email".into(), sv(r.get("email")));
        o.insert("birthday".into(), sv(r.get("birthday")));
        o.insert("language".into(), sv(r.get("language")));
        o.insert("accountName".into(), sv(r.get("accountname")));
        o.insert("active".into(), Value::Bool(r.get::<Option<bool>, _>("active").unwrap_or(false)));
        out.insert(id, o);
    }
    let found: Vec<i32> = out.keys().cloned().collect();
    let rrows = sqlx::query(
        "select ur.user_id, r.id, r.name, r.description from users_roles ur \
         join roles r on r.id = ur.role_id where ur.user_id = any($1) order by r.id",
    )
    .bind(found.clone())
    .fetch_all(pool)
    .await?;
    for r in rrows {
        let uid: i32 = r.get("user_id");
        let mut ro = new_instance(Kind::Role);
        ro.insert("id".into(), json!(r.get::<i32, _>("id")));
        ro.insert("name".into(), sv(r.get("name")));
        ro.insert("description".into(), sv(r.get("description")));
        if let Some(Value::Array(a)) = out.get_mut(&uid).and_then(|o| o.get_mut("roles")) {
            a.push(Value::Object(ro));
        }
    }
    let grows = sqlx::query("select user_id, usergroup_id from user_usergroup where user_id = any($1) order by usergroup_id")
        .bind(found)
        .fetch_all(pool)
        .await?;
    for r in grows {
        let uid: i32 = r.get("user_id");
        if let Some(Value::Array(a)) = out.get_mut(&uid).and_then(|o| o.get_mut("userGroups")) {
            a.push(json!(r.get::<i32, _>("usergroup_id")));
        }
    }
    Ok(out)
}

pub async fn groups(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, Obj>> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query("select id, name, owner_id from usergroups where id = any($1)")
        .bind(ids.to_vec())
        .fetch_all(pool)
        .await?;
    let mut owners: HashMap<i32, i32> = HashMap::new();
    for r in rows {
        let mut o = new_instance(Kind::Group);
        let id: i32 = r.get("id");
        o.insert("id".into(), json!(id));
        o.insert("name".into(), sv(r.get("name")));
        if let Some(ow) = r.get::<Option<i32>, _>("owner_id") {
            owners.insert(id, ow);
        }
        out.insert(id, o);
    }
    let found: Vec<i32> = out.keys().cloned().collect();
    let mrows = sqlx::query("select usergroup_id, user_id from user_usergroup where usergroup_id = any($1) order by user_id")
        .bind(found.clone())
        .fetch_all(pool)
        .await?;
    let mut members: Vec<(i32, i32)> = vec![];
    for r in mrows {
        members.push((r.get("usergroup_id"), r.get("user_id")));
    }
    let mut user_ids: HashSet<i32> = owners.values().cloned().collect();
    user_ids.extend(members.iter().map(|m| m.1));
    let user_ids: Vec<i32> = user_ids.into_iter().collect();
    let umap = users(pool, &user_ids).await?;
    for (gid, uid) in members {
        if let (Some(u), Some(Value::Array(a))) = (umap.get(&uid), out.get_mut(&gid).and_then(|o| o.get_mut("members"))) {
            a.push(Value::Object(u.clone()));
        }
    }
    for (gid, uid) in owners {
        if let (Some(u), Some(o)) = (umap.get(&uid), out.get_mut(&gid)) {
            o.insert("owner".into(), Value::Object(u.clone()));
        }
    }
    let rrows = sqlx::query(
        "select gr.usergroup_id, r.id, r.name, r.description from usergroups_roles gr \
         join roles r on r.id = gr.role_id where gr.usergroup_id = any($1) order by r.id",
    )
    .bind(found)
    .fetch_all(pool)
    .await?;
    for r in rrows {
        let gid: i32 = r.get("usergroup_id");
        let mut ro = new_instance(Kind::Role);
        ro.insert("id".into(), json!(r.get::<i32, _>("id")));
        ro.insert("name".into(), sv(r.get("name")));
        ro.insert("description".into(), sv(r.get("description")));
        if let Some(Value::Array(a)) = out.get_mut(&gid).and_then(|o| o.get_mut("roles")) {
            a.push(Value::Object(ro));
        }
    }
    Ok(out)
}

pub async fn appearances(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, Obj>> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query(
        "select id, attribution, hoverable, clickable, hovertemplate, name, maxresolution, minresolution, \
         opacity, visible from layerappearances where id = any($1)",
    )
    .bind(ids.to_vec())
    .fetch_all(pool)
    .await?;
    for r in rows {
        let mut o = new_instance(Kind::Appearance);
        let id: i32 = r.get("id");
        o.insert("id".into(), json!(id));
        o.insert("attribution".into(), sv(r.get("attribution")));
        o.insert("hoverable".into(), bv(r.get("hoverable")));
        o.insert("clickable".into(), bv(r.get("clickable")));
        o.insert("hoverTemplate".into(), sv(r.get("hovertemplate")));
        o.insert("name".into(), sv(r.get("name")));
        o.insert("maxResolution".into(), dv(r.get("maxresolution")));
        o.insert("minResolution".into(), dv(r.get("minresolution")));
        o.insert("opacity".into(), dv(r.get("opacity")));
        o.insert("visible".into(), bv(r.get("visible")));
        out.insert(id, o);
    }
    let found: Vec<i32> = out.keys().cloned().collect();
    let prows = sqlx::query(
        "select appearance_id, property, value from layerappearances_properties where appearance_id = any($1) order by property",
    )
    .bind(found)
    .fetch_all(pool)
    .await?;
    for r in prows {
        let aid: i32 = r.get("appearance_id");
        let key: String = r.get("property");
        let val: Option<String> = r.get("value");
        if let (Some(v), Some(Value::Object(m))) = (val, out.get_mut(&aid).and_then(|o| o.get_mut("properties"))) {
            m.insert(key, property_from_db(&v));
        }
    }
    Ok(out)
}

pub async fn extents(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, Obj>> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query(
        "select id, lowerleft_x, lowerleft_y, upperright_x, upperright_y from extents where id = any($1)",
    )
    .bind(ids.to_vec())
    .fetch_all(pool)
    .await?;
    for r in rows {
        let mut o = new_instance(Kind::Extent);
        let id: i32 = r.get("id");
        o.insert("id".into(), json!(id));
        o.insert("lowerLeft".into(), point(r.get("lowerleft_x"), r.get("lowerleft_y")));
        o.insert("upperRight".into(), point(r.get("upperright_x"), r.get("upperright_y")));
        out.insert(id, o);
    }
    Ok(out)
}

pub async fn tilegrids(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, (Kind, Obj)>> {
    let mut out: HashMap<i32, (Kind, Obj)> = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query(
        "select t.id, t.type, t.tilegridorigin_x, t.tilegridorigin_y, t.tilesize, t.tilegridextent_id, \
         (w.id is not null) as is_wmts from tilegrids t left join wmtstilegrids w on w.id = t.id where t.id = any($1)",
    )
    .bind(ids.to_vec())
    .fetch_all(pool)
    .await?;
    let mut extent_ids = vec![];
    let mut extent_of: HashMap<i32, i32> = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        let wmts: bool = r.get::<Option<bool>, _>("is_wmts").unwrap_or(false);
        let kind = if wmts { Kind::WmtsTileGrid } else { Kind::TileGrid };
        let mut o = new_instance(kind);
        o.insert("id".into(), json!(id));
        o.insert("type".into(), sv(r.get("type")));
        o.insert(
            "tileGridOrigin".into(),
            point(r.get("tilegridorigin_x"), r.get("tilegridorigin_y")),
        );
        o.insert("tileSize".into(), iv(r.get("tilesize")));
        o.insert("tileGridResolutions".into(), json!([]));
        if wmts {
            o.insert("matrixIds".into(), json!([]));
        }
        if let Some(e) = r.get::<Option<i32>, _>("tilegridextent_id") {
            extent_ids.push(e);
            extent_of.insert(id, e);
        }
        out.insert(id, (kind, o));
    }
    let found: Vec<i32> = out.keys().cloned().collect();
    let rrows = sqlx::query("select tilegrid_id, resolution from tilegrid_resolution where tilegrid_id = any($1) order by tilegrid_id, idx")
        .bind(found.clone())
        .fetch_all(pool)
        .await?;
    for r in rrows {
        let tid: i32 = r.get("tilegrid_id");
        if let (Some(d), Some((_, o))) = (r.get::<Option<f64>, _>("resolution"), out.get_mut(&tid)) {
            if let Some(Value::Array(a)) = o.get_mut("tileGridResolutions") {
                a.push(json!(d));
            }
        }
    }
    let mrows = sqlx::query("select wmtstilegrids_id, matrixids from wmtstilegrids_matrixids where wmtstilegrids_id = any($1)")
        .bind(found)
        .fetch_all(pool)
        .await?;
    for r in mrows {
        let tid: i32 = r.get("wmtstilegrids_id");
        if let (Some(s), Some((_, o))) = (r.get::<Option<String>, _>("matrixids"), out.get_mut(&tid)) {
            if let Some(Value::Array(a)) = o.get_mut("matrixIds") {
                a.push(Value::String(s));
            }
        }
    }
    let emap = extents(pool, &extent_ids).await?;
    for (tid, eid) in extent_of {
        if let (Some(e), Some((_, o))) = (emap.get(&eid), out.get_mut(&tid)) {
            o.insert("tileGridExtent".into(), Value::Object(e.clone()));
        }
    }
    Ok(out)
}

pub async fn datasources(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, (Kind, Obj)>> {
    let mut out: HashMap<i32, (Kind, Obj)> = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query(
        "select d.id, d.name, d.type, d.url, d.format, \
         i.id as i_id, i.width, i.height, i.version as i_version, i.layernames, i.layerstyles, \
         i.requestablebypath, i.customrequestpath, \
         t.id as t_id, t.request_with_tiled, t.tilegrid_id as t_tg, \
         w.id as w_id, w.typename, w.typenames, w.version as w_version, \
         m.id as m_id, m.capabilitiesurl, m.matrixset, m.projection, m.requestencoding, m.wmtslayer, \
         m.wmtsstyle, m.tilegrid_id as m_tg, \
         x.id as x_id, x.center_x, x.center_y, x.tilesize, x.extent_id \
         from layerdatasources d \
         left join imagewmslayerdatasources i on i.id = d.id \
         left join tilewmslayerdatasources t on t.id = d.id \
         left join wfslayerdatasources w on w.id = d.id \
         left join wmtslayerdatasources m on m.id = d.id \
         left join xyzlayerdatasources x on x.id = d.id \
         where d.id = any($1)",
    )
    .bind(ids.to_vec())
    .fetch_all(pool)
    .await?;
    let mut tg_ids = vec![];
    let mut ex_ids = vec![];
    // (ds id, tilegrid id) / (ds id, extent id)
    let mut tg_of: HashMap<i32, i32> = HashMap::new();
    let mut ex_of: HashMap<i32, i32> = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        let is = |c: &str| r.get::<Option<i32>, _>(c).is_some();
        let kind = if is("t_id") {
            Kind::DsTile
        } else if is("i_id") {
            Kind::DsImage
        } else if is("w_id") {
            Kind::DsWfs
        } else if is("m_id") {
            Kind::DsWmts
        } else if is("x_id") {
            Kind::DsXyz
        } else {
            continue;
        };
        let mut o = new_instance(kind);
        o.insert("id".into(), json!(id));
        o.insert("name".into(), sv(r.get("name")));
        o.insert("type".into(), sv(r.get("type")));
        o.insert("url".into(), sv(r.get("url")));
        o.insert("format".into(), sv(r.get("format")));
        match kind {
            Kind::DsTile | Kind::DsImage => {
                o.insert("width".into(), json!(r.get::<Option<i32>, _>("width").unwrap_or(0)));
                o.insert("height".into(), json!(r.get::<Option<i32>, _>("height").unwrap_or(0)));
                o.insert("version".into(), sv(r.get("i_version")));
                o.insert("layerNames".into(), sv(r.get("layernames")));
                o.insert("layerStyles".into(), sv(r.get("layerstyles")));
                o.insert("requestableByPath".into(), bv(r.get("requestablebypath")));
                o.insert("customRequestPath".into(), sv(r.get("customrequestpath")));
                if kind == Kind::DsTile {
                    o.insert("requestWithTiled".into(), bv(r.get("request_with_tiled")));
                    if let Some(t) = r.get::<Option<i32>, _>("t_tg") {
                        tg_ids.push(t);
                        tg_of.insert(id, t);
                    }
                }
            }
            Kind::DsWfs => {
                o.insert("version".into(), sv(r.get("w_version")));
                o.insert("typeName".into(), sv(r.get("typename")));
                o.insert("typeNames".into(), sv(r.get("typenames")));
            }
            Kind::DsWmts => {
                o.insert("urls".into(), json!([]));
                o.insert("wmtsLayer".into(), sv(r.get("wmtslayer")));
                o.insert("wmtsStyle".into(), sv(r.get("wmtsstyle")));
                o.insert("projection".into(), sv(r.get("projection")));
                o.insert("matrixSet".into(), sv(r.get("matrixset")));
                o.insert("requestEncoding".into(), sv(r.get("requestencoding")));
                o.insert("capabilitiesUrl".into(), sv(r.get("capabilitiesurl")));
                if let Some(t) = r.get::<Option<i32>, _>("m_tg") {
                    tg_ids.push(t);
                    tg_of.insert(id, t);
                }
            }
            Kind::DsXyz => {
                o.insert("center".into(), point(r.get("center_x"), r.get("center_y")));
                o.insert("tileSize".into(), iv(r.get("tilesize")));
                if let Some(e) = r.get::<Option<i32>, _>("extent_id") {
                    ex_ids.push(e);
                    ex_of.insert(id, e);
                }
            }
            _ => {}
        }
        out.insert(id, (kind, o));
    }
    let found: Vec<i32> = out.keys().cloned().collect();
    // wmts urls
    let urows = sqlx::query("select wmtslayerdatasources_id, urls from wmtslayerdatasources_urls where wmtslayerdatasources_id = any($1)")
        .bind(found.clone())
        .fetch_all(pool)
        .await?;
    for r in urows {
        let did: i32 = r.get("wmtslayerdatasources_id");
        if let (Some(u), Some((_, o))) = (r.get::<Option<String>, _>("urls"), out.get_mut(&did)) {
            if let Some(Value::Array(a)) = o.get_mut("urls") {
                a.push(Value::String(u));
            }
        }
    }
    // xyz resolutions
    let xrows = sqlx::query("select xyzlayerdatasrc_id, resolution from xyzlayerdatasrc_resolution where xyzlayerdatasrc_id = any($1) order by xyzlayerdatasrc_id, idx")
        .bind(found)
        .fetch_all(pool)
        .await?;
    for r in xrows {
        let did: i32 = r.get("xyzlayerdatasrc_id");
        if let (Some(b), Some((_, o))) = (r.get::<Option<Vec<u8>>, _>("resolution"), out.get_mut(&did)) {
            if let Some(Value::Array(a)) = o.get_mut("resolutions") {
                a.push(json!(decode_resolution(&b)));
            }
        }
    }
    let tmap = tilegrids(pool, &tg_ids).await?;
    for (did, tid) in tg_of {
        if let (Some((_, t)), Some((_, o))) = (tmap.get(&tid), out.get_mut(&did)) {
            o.insert("tileGrid".into(), Value::Object(t.clone()));
        }
    }
    let emap = extents(pool, &ex_ids).await?;
    for (did, eid) in ex_of {
        if let (Some(e), Some((_, o))) = (emap.get(&eid), out.get_mut(&did)) {
            o.insert("extent".into(), Value::Object(e.clone()));
        }
    }
    Ok(out)
}

pub async fn layers(pool: &PgPool, ids: &[i32]) -> Res<HashMap<i32, Obj>> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    let rows = sqlx::query("select id, name, description, appearance_id, source_id from layers where id = any($1)")
        .bind(ids.to_vec())
        .fetch_all(pool)
        .await?;
    let mut app_of = HashMap::new();
    let mut src_of = HashMap::new();
    for r in rows {
        let mut o = new_instance(Kind::Layer);
        let id: i32 = r.get("id");
        o.insert("id".into(), json!(id));
        o.insert("name".into(), sv(r.get("name")));
        o.insert("description".into(), sv(r.get("description")));
        if let Some(a) = r.get::<Option<i32>, _>("appearance_id") {
            app_of.insert(id, a);
        }
        if let Some(s) = r.get::<Option<i32>, _>("source_id") {
            src_of.insert(id, s);
        }
        out.insert(id, o);
    }
    let app_ids: Vec<i32> = app_of.values().cloned().collect();
    let src_ids: Vec<i32> = src_of.values().cloned().collect();
    let amap = appearances(pool, &app_ids).await?;
    let smap = datasources(pool, &src_ids).await?;
    for (lid, aid) in app_of {
        if let (Some(a), Some(o)) = (amap.get(&aid), out.get_mut(&lid)) {
            o.insert("appearance".into(), Value::Object(a.clone()));
        }
    }
    for (lid, sid) in src_of {
        if let (Some((_, s)), Some(o)) = (smap.get(&sid), out.get_mut(&lid)) {
            o.insert("source".into(), Value::Object(s.clone()));
        }
    }
    Ok(out)
}

