tool_use_result.content:
//! Loading entities (with the associations Hibernate fetches eagerly) from the
//! database into in-memory [`Obj`]s.

use crate::javafmt::property_from_db;
use crate::spec::{new_instance, Kind, Obj};
use serde_json::{json, Value};
use sqlx::{PgPool, Row};
use std::collections::{HashMap, HashSet};

pub type Res<T> = Result<T, sqlx::Error>;

fn sv(v: Option<String>) -> Value {
    v.map(Value::String).unwrap_or(Value::Null)
}
fn iv(v: Option<i32>) -> Value {
    v.map(|x| json!(x)).unwrap_or(Value::Null)
}
fn bv(v: Option<bool>) -> Value {
    v.map(Value::Bool).unwrap_or(Value::Null)
}
fn dv(v: Option<f64>) -> Value {
    v.map(|x| json!(x)).unwrap_or(Value::Null)
}
fn point(x: Option<f64>, y: Option<f64>) -> Value {
    if x.is_none() && y.is_none() {
        Value::Null
    } else {
        json!({"x": x.unwrap_or(0.0), "y": y.unwrap_or(0.0)})
    }
}

pub fn decode_resolution(bytes: &[u8]) -> f64 {
    if bytes.len() >= 8 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&bytes[bytes.len() - 8..]);
        f64::from_be_bytes(b)
    } else {
        0.0
    }
}

const DOUBLE_PREFIX: [u8; 0x4d] = [
    0xac, 0xed, 0x00, 0x05, 0x73, 0x72, 0x00, 0x10, b'j', b'a', b'v', b'a', b'.', b'l', b'a', b'n', b'g', b'.',
    b'D', b'o', b'u', b'b', b'l', b'e', 0x80, 0xb3, 0xc2, 0x4a, 0x29, 0x6b, 0xfb, 0x04, 0x02, 0x00, 0x01, b'D',
    0x00, 0x05, b'v', b'a', b'l', b'u', b'e', 0x78, 0x72, 0x00, 0x10, b'j', b'a', b'v', b'a', b'.', b'l', b'a',
    b'n', b'g', b'.', b'N', b'u', b'm', b'b', b'e', b'r', 0x86, 0xac, 0x95, 0x1d, 0x0b, 0x94, 0xe0, 0x8b, 0x02,
    0x00, 0x00, 0x78, 0x70,
];

/// Java serialisation of a `java.lang.Double`.
pub fn encode_resolution(d: f64) -> Vec<u8> {
    let mut v = DOUBLE_PREFIX.to_vec();
    v.extend_from_slice(&d.to_be_bytes());
    v
}

