mod app;
mod javafmt;
mod load;
mod spec;
mod store;

use axum::body::Body;
use axum::extract::{Request, State};
use axum::response::Response;
use axum::Router;
use sqlx::postgres::PgPoolOptions;
use std::sync::Arc;

async fn handler(State(app): State<Arc<app::App>>, req: Request<Body>) -> Response {
    app.handle(req).await
}

#[tokio::main]
async fn main() {
    let url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let port: u16 = std::env::var("PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(8080);
    let mut pool = None;
    for _ in 0..60 {
        match PgPoolOptions::new().max_connections(20).connect(&url).await {
            Ok(p) => {
                pool = Some(p);
                break;
            }
            Err(e) => {
                eprintln!("waiting for database: {e}");
                tokio::time::sleep(std::time::Duration::from_secs(1)).await;
            }
        }
    }
    let pool = pool.expect("cannot connect to the database");
    let state = Arc::new(app::App::new(pool));
    let router = Router::new().fallback(handler).with_state(state);
    let listener = tokio::net::TcpListener::bind(("0.0.0.0", port)).await.expect("cannot bind");
    axum::serve(listener, router).await.unwrap();
}

